package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.EmployeeShiftPreferenceRequest; import EmployeeManagementSystem.repository.EmployeeShiftPreferenceRequestRepository; import org.springframework.stereotype.Service; import java.time.*; import java.util.*;
@Service public class EmployeeShiftPreferenceRequestServiceImpl implements EmployeeShiftPreferenceRequestService{
 private final EmployeeShiftPreferenceRequestRepository repo; public EmployeeShiftPreferenceRequestServiceImpl(EmployeeShiftPreferenceRequestRepository r){repo=r;}
 public List<EmployeeShiftPreferenceRequest> my(String u){return repo.findByUserIdOrderByCreatedAtDesc(u);} public List<EmployeeShiftPreferenceRequest> all(){return repo.findAllByOrderByCreatedAtDesc();}
 public EmployeeShiftPreferenceRequest create(EmployeeShiftPreferenceRequest x,String u,String n){if(x.getPreferredShift()==null||x.getPreferredShift().isBlank())throw new IllegalArgumentException("Preferred shift is required."); if(x.getReason()==null||x.getReason().isBlank())throw new IllegalArgumentException("Reason is required."); if(x.getEffectiveDate()!=null&&x.getEffectiveDate().isBefore(LocalDate.now()))throw new IllegalArgumentException("Effective date cannot be in the past."); if(repo.existsByUserIdAndStatusIn(u,List.of("SUBMITTED","UNDER_REVIEW")))throw new IllegalArgumentException("An active shift preference request already exists."); x.setId(null);x.setRequestNumber("SHP-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("SUBMITTED");return repo.save(x);}
 public EmployeeShiftPreferenceRequest review(Long id,String s,String c,String r){EmployeeShiftPreferenceRequest x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Shift preference request not found.")); if(!Set.of("UNDER_REVIEW","APPROVED","REJECTED","CANCELLED").contains(s))throw new IllegalArgumentException("Invalid request status."); x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setReviewedAt(LocalDateTime.now());return repo.save(x);}
}
